INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('06a13ff8-8b17-475f-a67e-31d2a1d53a4d', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '8e37c137-4791-470c-8af2-f9ef087d76f6', 'Tags an attribute as one that declares a slot relationship between a component and an attribute it expects members to carry -- regardless of whether that expectation is enforced as an error, a warning, or purely informational.', 'str');
