INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('d6653479-cf64-4057-8c7f-1e9e89e25546', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '8a707bcb-7ff7-488f-b7e3-b1679f823c95', 'Declares that entities carrying a given component are expected to have at least one statement using the given attribute; absence is worth a warning, not an error, and signals data worth completing.', 'str');
