INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('e3a37884-a65a-49fc-a9f2-828e04adbadc', '9ca34038-1a65-4ede-88c5-1492ab4bc249', 'e8d0e88d-a8ea-4612-8e8c-a4be732d1a93', 'Declares that entities carrying a given component may have this attribute, for table and schema discovery purposes only -- its absence has no validation consequence.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('b73f9ca7-ca4d-4562-868b-205b57b832c7', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', 'd9496c5d-6e55-43ca-84bf-72d565c33419', 'theProvenance', 'str');
