INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('bd097fe2-6789-464b-a168-c42b7261480d', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '622966de-0519-4a9b-a2d5-95a99850ba42', 'ProvenanceInfo', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('01d73853-6b8a-4885-9082-fda0f0fa5399', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '622966de-0519-4a9b-a2d5-95a99850ba42', 'A way to tell who put this information together and when.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('351fb2fd-4f41-4970-8aa6-337be8054e13', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '0cacaa3b-d1be-4314-9644-a65baff03a63', 'theSelfDescribingProvenance', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('cea49add-30da-4e13-b4d3-a4a64455780b', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '0cacaa3b-d1be-4314-9644-a65baff03a63', 'Used exactly once per ProvenanceInfo entity, pointing it at itself. Terminates the regress of every provenance statement needing its own provenance -- the same trick as theName of theName.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('2e3a8dd9-019e-4649-8004-703d97a228e8', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '8f9dc95b-c4d3-4500-9a6c-9ddc63cdecf9', 'aReplacement', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('ad98fcc1-0ba2-45fb-a13e-6161d368ff98', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '8f9dc95b-c4d3-4500-9a6c-9ddc63cdecf9', 'Points from an older statement''s handle (or an older entity) to the newer statement or entity that supersedes it. A reader should prefer the value(s) here over the item bearing this statement''s entity, unless something else in turn has an aReplacement pointing away from that item too -- walk the chain to find the current one. Multi-valued: an old item may have been superseded by more than one new item (e.g. split into two). Nothing in this store carries a timestamp, so recency is inferred only by following this chain, never by row order.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('495fcc9e-67ac-4eed-bc2d-d0c06338a4b8', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '1c260a46-c907-4efc-adb2-9345aebd9500', 'anErratum', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('d34906eb-27e0-4a2d-8b53-a44fae149877', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '1c260a46-c907-4efc-adb2-9345aebd9500', 'Free text flagging that the statement or entity carrying this (by UUID) should never have existed as asserted -- a mistake, not a later legitimate change. Multi-valued (anErratum, not theErratum) since an item could be wrong for more than one reason. Distinct from aReplacement, which chains a sequence of states each true in their own time -- anErratum instead marks something void from the start. Could become a full component later if a flagged item ever needs more than free text attached.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('171f17e6-b3d2-413b-aef3-99e7f130b018', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '29a25e0e-3f32-4787-965e-3ecc917d6fef', 'aNote', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('a5caef25-900e-4fda-971b-15d017361576', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '29a25e0e-3f32-4787-965e-3ecc917d6fef', 'Free text. Deliberately left unspecified -- no fixed meaning is imposed on what this note should contain.', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('ef076b6d-00ee-453c-ba2b-f0f2b14cbb2b', 'acf5cebb-8d80-45ad-9a1f-a3dd48682ef6', '9084efd2-1fcf-492e-9ec1-63ef91691f47', 'aReferencedUUID', 'str');
INSERT INTO statements (handle, attribute, entity, value, value_type) VALUES ('badb07b4-255c-4889-9c8b-49b70052cd1b', '9ca34038-1a65-4ede-88c5-1492ab4bc249', '9084efd2-1fcf-492e-9ec1-63ef91691f47', 'Declares that a document or piece of code hardcodes the given UUID because that''s the shape best to operate on. Lets a data steward find every place an item is used -- useful for keeping items up to date, or seeing how an item is used in context.', 'str');
