-- Trunky starter kit: the bootstrap concepts llms.txt documents (theName/
-- theIntention rows for each). These reuse the exact handles from the
-- original database on purpose -- this is a copy of Mark's own original
-- assertions, not a fresh independent claim by whoever applies this file,
-- so the handles matching IS the provenance, no chain-of-custody system
-- needed to know these trace back to the same original statements.
-- No ProvenanceInfo instance is seeded -- provenance is optional and
-- unchecked at write time (see api_server.py's _post_single/_post_bulk).
-- Apply with: sqlite3 lignin.db < starter.sql

CREATE TABLE IF NOT EXISTS statements (
    handle     TEXT PRIMARY KEY,
    attribute  TEXT NOT NULL,
    entity     TEXT NOT NULL,
    value      TEXT NOT NULL,
    value_type TEXT NOT NULL CHECK (value_type IN ('uuid', 'str', 'int'))
);
CREATE INDEX IF NOT EXISTS idx_statements_entity ON statements(entity);
CREATE INDEX IF NOT EXISTS idx_statements_attribute ON statements(attribute);
CREATE INDEX IF NOT EXISTS idx_statements_attr_entity ON statements(attribute, entity);
CREATE INDEX IF NOT EXISTS idx_statements_value ON statements(value);

